head.script:
scwin.screenId = "uldmgt50208";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50208.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_22_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_22_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_22_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.excel()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50208.img_22_onclick' }); }
};

/**
 * @event
 * @name scwin.img_24_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_24_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_24_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.popInsert()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50208.img_24_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/editClass.do",
        ref: "dma_ExcelReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50208.tx_fn_Excel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_List_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_Delete_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Delete_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr", unresolved: "action:self_submit:tx_fn_Delete_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "findEditUpclasses");
    await scwin.tx_fn_List_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('txt_listDiv').setValue(responseText);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.midclassList
 * @author Inswave
 * @date 2026. 09. 29
 * @param upEditClssCd
 * @returns
 * @hidden N
*/
scwin.midclassList = function (upEditClssCd) {
    /* sdd-asis-lifecycle:begin fn_MidclassList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    goURL("/filing/editClass.do?method=findEditMidclassList&upEditClssCd=" + upEditClssCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.popInsert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.popInsert = async function () {
    /* sdd-asis-lifecycle:begin popInsert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/editClass.do?method=prepareUpdateEditUpclass&mode=create";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "upclassPop", popupName: "upclassPop", width: "380", height: "270" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.popModify
 * @author Inswave
 * @date 2026. 09. 29
 * @param editClssCd
 * @returns
 * @hidden N
*/
scwin.popModify = async function (editClssCd) {
    /* sdd-asis-lifecycle:begin fn_PopModify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/editClass.do?method=prepareUpdateEditUpclass&editClssCd=" + editClssCd + "&mode=update";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "upclassPop", popupName: "upclassPop", width: "400", height: "260" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteExcelReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param editClssCd editClssNm
 * @returns
 * @hidden N
*/
scwin.deleteExcelReq = async function (editClssCd, editClssNm) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("편집기대분류 '" + editClssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ExcelReq').set('editClssCd', editClssCd);
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "deleteEditUpclass");
    await scwin.tx_fn_Delete_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excel = async function () {
    /* sdd-asis-lifecycle:begin fn_Excel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "downloadEditUpclassList");
    scwin.form_listForm.target = "hiddenFrame";
    await scwin.tx_fn_Excel();
    /* sdd-asis-lifecycle:end */
};
